 static void Calendar(Graphics g,DateTime now,DateTime month,State s){string title=month.ToString("MMMM yyyy",Program.Ru);title=char.ToUpper(title[0],Program.Ru)+title.Substring(1);T(g,title,15,Text,20,25,true);C(g,"‹",new Rectangle(281,15,29,32),24,Muted);C(g,"›",new Rectangle(314,15,29,32),24,Muted);string[] days={"Пн","Вт","Ср","Чт","Пт","Сб","Вс"};for(int i=0;i<7;i++)C(g,days[i],new Rectangle(18+i*46,61,44,22),11,Muted);
