 static string Temp(double n){return (n>0?"+":"")+Math.Round(n).ToString(CultureInfo.InvariantCulture)+"°";}
 static string Desc(int c){if(c==0)return "Ясно";if(c<=2)return "Облачно с прояснениями";if(c<=3)return "Облачно";if(c<=48)return "Туман";if(c<=57)return "Морось";if(c<=67)return "Дождь";if(c==69)return "Мокрый снег";if(c<=77)return "Снег";if(c<=82)return "Ливни";if(c<=86)return "Снегопад";return "Гроза";}
