 Scene.WeatherIcon(g,21,65,w.current.weather_code,62);T(g,Temp(w.current.temperature_2m)+"C",35,Text,97,65,true);Fit(g,Desc(w.current.weather_code),new Rectangle(99,108,243,20),12,Text);string detail=(w.current.relative_humidity_2m.HasValue?"Влажность "+Math.Round(w.current.relative_humidity_2m.Value)+"%":"Ощущается "+Temp(w.current.apparent_temperature))+" · Ветер "+w.current.wind_speed_10m.ToString("0.#")+" м/с";Fit(g,detail,new Rectangle(99,131,243,20),10,Muted);
 Line(g,AppTheme.Edge,18,163,342,163);DateTime cityNow;if(!DateTime.TryParse(w.current.time,CultureInfo.InvariantCulture,DateTimeStyles.None,out cityNow))cityNow=now;int col=0;for(int i=0;i<w.daily.time.Length&&col<7;i++){DateTime d;if(!DateTime.TryParse(w.daily.time[i],out d)||d.Date<=cityNow.Date)continue;int x=21+col*46;C(g,d.ToString("ddd",Program.Ru),new Rectangle(x,174,42,18),10,Muted);Scene.WeatherIcon(g,x+8,197,w.daily.weather_code[i],27);C(g,Temp(w.daily.temperature_2m_max[i]),new Rectangle(x,229,42,18),11,Text,true);C(g,Temp(w.daily.temperature_2m_min[i]),new Rectangle(x,248,42,18),10,Muted);col++;}Fit(g,(w.Provider??"Погода")+" · "+status,new Rectangle(20,269,320,13),8,Muted);
 }
 public static Color CardColor(Note n){Color[] light={Color.FromArgb(255,245,187),Color.FromArgb(212,235,253),Color.FromArgb(215,240,219),Color.FromArgb(249,220,239)};Color[] dark={Color.FromArgb(78,66,29),Color.FromArgb(30,58,79),Color.FromArgb(31,66,46),Color.FromArgb(76,42,64)};return (AppTheme.Light?light:dark)[NoteCards.ColorIndex(n)];}
 static void Notes(Graphics g,State s,int scroll){T(g,"Заметки",12,Muted,20,25);NoteHeader.DrawPlus(g);var save=g.Save();g.SetClip(new Rectangle(12,NoteCards.Top,336,NoteCards.Bottom-NoteCards.Top));foreach(var card in NoteCards.Layout(s,scroll)){var r=card.Bounds;if(r.Bottom<NoteCards.Top||r.Top>NoteCards.Bottom)continue;Box(g,r,CardColor(card.Note),9);Fit(g,card.Note.Title,new Rectangle(r.X+14,r.Y+12,r.Width-28,23),14,Text,true);if(card.Checklist){for(int i=0;i<card.Lines.Count;i++){var l=card.Lines[i];int y=r.Y+43+i*24;if(l.Task){var cb=new Rectangle(r.X+14,y+1,16,16);Box(g,cb,l.Done?Accent:AppTheme.Pick(Color.FromArgb(242,242,239),Color.White),3);if(l.Done){Line(g,Color.White,cb.X+4,cb.Y+8,cb.X+7,cb.Y+11,1.8f);Line(g,Color.White,cb.X+7,cb.Y+11,cb.X+12,cb.Y+4,1.8f);}else using(var pen=new Pen(Color.FromArgb(153,159,164)))g.DrawRectangle(pen,cb);Fit(g,l.Text,new Rectangle(r.X+40,y,r.Width-52,22),12,l.Done?Muted:Text);if(l.Done)Line(g,Muted,r.X+40,y+8,Math.Min(r.Right-14,r.X+40+l.Text.Length*6),y+8);}else Fit(g,l.Text,new Rectangle(r.X+14,y,r.Width-28,22),12,Text);}}else Fit(g,(card.Note.Body??"").Trim(),new Rectangle(r.X+14,r.Y+39,r.Width-28,r.Height-46),12,Text,false,true);}
 if(s.Notes.Count==0){C(g,"Здесь будут твои заметки",new Rectangle(20,182,320,30),16,Text,true);C(g,"Текст, идеи и списки дел — всё рядом",new Rectangle(20,223,320,24),12,Muted);}g.Restore(save);if(NoteCards.MaxScroll(s)>0){int viewportHeight=NoteCards.Bottom-NoteCards.Top,total=NoteCards.MaxScroll(s)+viewportHeight,thumb=Math.Max(25,viewportHeight*viewportHeight/total),y=NoteCards.Top+(viewportHeight-thumb)*Math.Max(0,Math.Min(scroll,NoteCards.MaxScroll(s)))/NoteCards.MaxScroll(s);Box(g,new Rectangle(347,y,2,thumb),AppTheme.Edge,1);}
